#include <stdio.h>
#include <sys/ioctl.h>
#include <linux/ppdev.h>
#include <linux/parport.h>

int main() {
    printf("# PP_IOCTL = 'p' = %d\n", 'p');

    printf("\n# Ioctls\n");
    printf("PPSETMODE = %lu\n", (unsigned long)PPSETMODE);
    printf("PPRSTATUS = %lu\n", (unsigned long)PPRSTATUS);
    printf("PPRCONTROL = %lu\n", (unsigned long)PPRCONTROL);
    printf("PPWCONTROL = %lu\n", (unsigned long)PPWCONTROL);
    printf("PPFCONTROL = %lu\n", (unsigned long)PPFCONTROL);
    printf("PPRDATA = %lu\n", (unsigned long)PPRDATA);
    printf("PPWDATA = %lu\n", (unsigned long)PPWDATA);
    printf("PPCLAIM = %lu\n", (unsigned long)PPCLAIM);
    printf("PPRELEASE = %lu\n", (unsigned long)PPRELEASE);
    printf("PPYIELD = %lu\n", (unsigned long)PPYIELD);
    printf("PPEXCL = %lu\n", (unsigned long)PPEXCL);
    printf("PPDATADIR = %lu\n", (unsigned long)PPDATADIR);
    printf("PPNEGOT = %lu\n", (unsigned long)PPNEGOT);
    printf("PPWCTLONIRQ = %lu\n", (unsigned long)PPWCTLONIRQ);
    printf("PPCLRIRQ = %lu\n", (unsigned long)PPCLRIRQ);
    printf("PPSETPHASE = %lu\n", (unsigned long)PPSETPHASE);
    printf("PPGETTIME = %lu\n", (unsigned long)PPGETTIME);
    printf("PPSETTIME = %lu\n", (unsigned long)PPSETTIME);
    printf("PPGETMODES = %lu\n", (unsigned long)PPGETMODES);
    printf("PPGETMODE = %lu\n", (unsigned long)PPGETMODE);
    printf("PPGETPHASE = %lu\n", (unsigned long)PPGETPHASE);
    printf("PPGETFLAGS = %lu\n", (unsigned long)PPGETFLAGS);
    printf("PPSETFLAGS = %lu\n", (unsigned long)PPSETFLAGS);

    printf("\n# IEEE1284 mode flags\n");
    printf("IEEE1284_MODE_NIBBLE = %d\n", IEEE1284_MODE_NIBBLE);
    printf("IEEE1284_MODE_BYTE = %d\n", IEEE1284_MODE_BYTE);
    printf("IEEE1284_MODE_COMPAT = %d\n", IEEE1284_MODE_COMPAT);
    printf("IEEE1284_MODE_BECP = %d\n", IEEE1284_MODE_BECP);
    printf("IEEE1284_MODE_ECP = %d\n", IEEE1284_MODE_ECP);
    printf("IEEE1284_MODE_ECPRLE = %d\n", IEEE1284_MODE_ECPRLE);
    printf("IEEE1284_MODE_ECPSWE = %d\n", IEEE1284_MODE_ECPSWE);
    printf("IEEE1284_MODE_EPP = %d\n", IEEE1284_MODE_EPP);
    printf("IEEE1284_MODE_EPPSL = %d\n", IEEE1284_MODE_EPPSL);
    printf("IEEE1284_MODE_EPPSWE = %d\n", IEEE1284_MODE_EPPSWE);
    printf("IEEE1284_DEVICEID = %d\n", IEEE1284_DEVICEID);
    printf("IEEE1284_EXT_LINK = %d\n", IEEE1284_EXT_LINK);
    printf("IEEE1284_ADDR = %d\n", IEEE1284_ADDR);
    printf("IEEE1284_DATA = %d\n", IEEE1284_DATA);

    printf("\n# PP flags\n");
    printf("PP_FASTWRITE = %d\n", PP_FASTWRITE);
    printf("PP_FASTREAD = %d\n", PP_FASTREAD);
    printf("PP_W91284PIC = %d\n", PP_W91284PIC);

    return 0;
}
EOF
